import{_ as a}from"./chunks/lidar_lite_v3.B2gWESKa.js";import{_ as i,a as o}from"./chunks/lidar_lite_v3_pwm_wiring.drpKCofa.js";import{_ as n,C as s,o as d,c as l,j as t,a as h,E as p,al as c}from"./chunks/framework.7vp1BMOE.js";const L=JSON.parse('{"title":"Garmin LIDAR-Lite","description":"","frontmatter":{},"headers":[],"relativePath":"en/sensor/lidar_lite.md","filePath":"en/sensor/lidar_lite.md"}'),u={name:"en/sensor/lidar_lite.md"};function m(g,e,f,_,b,w){const r=s("Badge");return d(),l("div",null,[e[0]||(e[0]=t("h1",{id:"garmin-lidar-lite",tabindex:"-1"},[h("Garmin LIDAR-Lite "),t("a",{class:"header-anchor",href:"#garmin-lidar-lite","aria-label":'Permalink to "Garmin LIDAR-Lite"'},"​")],-1)),p(r,{type:"tip",text:"PX4 v1.1"}),e[1]||(e[1]=c('<p>The <a href="https://www.garmin.com/en-US/p/557294/" target="_blank" rel="noreferrer">Garmin LIDAR-Lite v3</a> is a compact laser time-of-flight <a href="./../sensor/rangefinders">rangefinder</a> with a range of up to 40 m (PX4 caps this to 35 m or less). It connects to the flight controller using either I2C or PWM.</p><p><img src="'+a+'" alt="LIDAR-Lite v3"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The driver for the PWM connection is not included in PX4 firmware by default. See <a href="#firmware_support">Firmware Support</a> for how to check your board and add it.</p></div><h2 id="supported_models" tabindex="-1">Supported Models <a class="header-anchor" href="#supported_models" aria-label="Permalink to &quot;Supported Models {#supported_models}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>Range</th><th>Connection</th><th>Notes</th></tr></thead><tbody><tr><td><a href="https://www.garmin.com/en-US/p/557294/" target="_blank" rel="noreferrer">LIDAR-Lite v3</a></td><td>Up to 40 m</td><td>I2C, PWM</td><td></td></tr><tr><td>LIDAR-Lite v3HP</td><td></td><td>I2C</td><td></td></tr><tr><td>LIDAR-Lite v4 LED</td><td></td><td>I2C</td><td>PX4 caps the range to 10 m.</td></tr><tr><td>LIDAR-Lite v2</td><td></td><td>I2C, PWM</td><td></td></tr><tr><td>LIDAR-Lite v1</td><td></td><td>I2C, PWM</td><td></td></tr></tbody></table><p>The rest of this page describes the LIDAR-Lite v3, unless otherwise stated.</p><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications {#specifications}&quot;">​</a></h2><p>The following specifications are for the LIDAR-Lite v3.</p><ul><li><strong>Technology:</strong> Laser time-of-flight (905 nm)</li><li><strong>Range:</strong> Up to 40 m (70% reflective target)</li><li><strong>Update rate:</strong> 270 Hz typical, 650 Hz in fast mode (PX4 samples at up to 100 Hz on I2C, and at 20 Hz on PWM)</li><li><strong>Beam divergence:</strong> 8 mrad</li><li><strong>Accuracy:</strong> ±2.5 cm typical below 5 m, ±10 cm typical at 5 m and above</li><li><strong>Resolution:</strong> ±1 cm</li><li><strong>Interface:</strong> I2C (address <code>0x62</code>), PWM</li><li><strong>Input voltage:</strong> 5 V DC nominal (4.5–5.5 V)</li><li><strong>Current draw:</strong> 105 mA idle, 135 mA in continuous operation</li><li><strong>Dimensions:</strong> 20 x 48 x 40 mm</li><li><strong>Weight:</strong> 22 g</li><li><strong>Operating temperature:</strong> -20 to 60 °C</li><li><strong>Laser class:</strong> Class 1</li></ul><h2 id="store" tabindex="-1">Where to Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where to Buy {#store}&quot;">​</a></h2><ul><li><a href="https://www.garmin.com/en-US/p/557294/" target="_blank" rel="noreferrer">LIDAR-Lite v3</a> (Garmin)</li></ul><h2 id="hardware_setup" tabindex="-1">Hardware Setup <a class="header-anchor" href="#hardware_setup" aria-label="Permalink to &quot;Hardware Setup {#hardware_setup}&quot;">​</a></h2><h3 id="mounting" tabindex="-1">Mounting <a class="header-anchor" href="#mounting" aria-label="Permalink to &quot;Mounting {#mounting}&quot;">​</a></h3><p>PX4 assumes that the rangefinder is facing down (the orientation cannot be configured).</p><h3 id="pinouts" tabindex="-1">Pinouts <a class="header-anchor" href="#pinouts" aria-label="Permalink to &quot;Pinouts {#pinouts}&quot;">​</a></h3><p>The LIDAR-Lite v3 has a 6-pin connector that mates with a JST GH housing (<code>GHR-06V-S</code>, 1.25 mm pitch).</p><table tabindex="0"><thead><tr><th>Pin</th><th>Wire colour</th><th>Signal</th><th>Description</th></tr></thead><tbody><tr><td>1</td><td>Red</td><td>5 V DC (+)</td><td>Power supply. 5 V DC nominal (4.5–5.5 V).</td></tr><tr><td>2</td><td>Orange</td><td>Power enable</td><td>Internal pull-up. Can be driven low to shut off power to the sensor.</td></tr><tr><td>3</td><td>Yellow</td><td>Mode control</td><td>PWM interface: pull low to trigger a measurement; returns a pulse (10 μs/cm).</td></tr><tr><td>4</td><td>Green</td><td>I2C SCL</td><td>I2C clock</td></tr><tr><td>5</td><td>Blue</td><td>I2C SDA</td><td>I2C data</td></tr><tr><td>6</td><td>Black</td><td>Ground (-)</td><td>Signal and power ground</td></tr></tbody></table><h3 id="wiring" tabindex="-1">Wiring <a class="header-anchor" href="#wiring" aria-label="Permalink to &quot;Wiring {#wiring}&quot;">​</a></h3><p>The LIDAR-Lite v3 can be connected using either I2C or PWM. Older LIDAR-Lite generations (v1 and v2) were reported to have I2C problems, and PWM was recommended for them.</p><p>The sensor requires a 5 V DC supply, and draws up to 135 mA in continuous operation. Check that the flight controller port can supply this, or power the sensor from a separate supply that shares a ground with the flight controller.</p><h4 id="wiring_i2c" tabindex="-1">I2C <a class="header-anchor" href="#wiring_i2c" aria-label="Permalink to &quot;I2C {#wiring_i2c}&quot;">​</a></h4><p>Connect the sensor to an external <code>I2C</code> port on the flight controller.</p><p><img src="'+i+'" alt="LIDAR-Lite v3 I2C wiring"></p><table tabindex="0"><thead><tr><th>LIDAR-Lite v3 pin</th><th>Wire colour</th><th>Connect to</th></tr></thead><tbody><tr><td>1 (5 V DC)</td><td>Red</td><td>5 V DC supply</td></tr><tr><td>4 (I2C SCL)</td><td>Green</td><td>Flight controller I2C SCL</td></tr><tr><td>5 (I2C SDA)</td><td>Blue</td><td>Flight controller I2C SDA</td></tr><tr><td>6 (Ground)</td><td>Black</td><td>Flight controller GND</td></tr></tbody></table><p>Pins 2 (power enable) and 3 (mode control) are not connected.</p><p>Garmin&#39;s standard I2C wiring also requires a 680 μF electrolytic capacitor between the 5 V DC and ground wires (observe the polarity).</p><p>The sensor uses the I2C address <code>0x62</code>.</p><h4 id="wiring_pwm" tabindex="-1">PWM <a class="header-anchor" href="#wiring_pwm" aria-label="Permalink to &quot;PWM {#wiring_pwm}&quot;">​</a></h4><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The PWM connection is not as well tested as I2C.</p></div><p>PX4 reads the sensor&#39;s PWM output on the flight controller&#39;s PWM input pin. On Pixhawk flight controllers this is FMU output 5 (<code>AUX 5</code>, or <code>MAIN 5</code> on flight controllers that have no AUX port). The pin is fixed.</p><p><img src="'+o+'" alt="LIDAR-Lite v3 PWM wiring"></p><table tabindex="0"><thead><tr><th>LIDAR-Lite v3 pin</th><th>Wire colour</th><th>Connect to</th></tr></thead><tbody><tr><td>1 (5 V DC)</td><td>Red</td><td>5 V DC supply</td></tr><tr><td>3 (Mode control)</td><td>Yellow</td><td><code>AUX 5</code> signal pin, and to ground through a resistor (below)</td></tr><tr><td>6 (Ground)</td><td>Black</td><td>Flight controller GND</td></tr></tbody></table><p>Pins 2 (power enable), 4 (I2C SCL) and 5 (I2C SDA) are not connected.</p><p>The mode control pin must be connected to ground through a resistor, which makes the sensor measure continuously. The Garmin specification is for a 1 kΩ resistor, but a 470 Ω resistor was found to be needed when tested with PX4 on a Pixhawk.</p><p>The driver also uses FMU output 6 (<code>AUX 6</code>), so this output cannot be used for anything else.</p><h2 id="firmware_support" tabindex="-1">Firmware Support <a class="header-anchor" href="#firmware_support" aria-label="Permalink to &quot;Firmware Support {#firmware_support}&quot;">​</a></h2><p>The rangefinder is supported by a different driver for each connection, as described below.</p><p>To check your board, look for the keys in its <a href="./../hardware/porting_guide_config">board configuration</a> file, <code>boards/&lt;vendor&gt;/&lt;board&gt;/default.px4board</code>.</p><p>If a driver is missing, add its key to the board&#39;s <code>default.px4board</code> file, or enable it in <a href="./../hardware/porting_guide_config#px4-menuconfig-setup">boardconfig</a> under <strong>Drivers &gt; Distance sensors</strong>, and then <a href="./../dev_setup/building_px4">build and upload the firmware</a>.</p><p>The drivers do not start until they are enabled using the parameter in <a href="#px4_configuration">PX4 Configuration</a>.</p><h3 id="firmware_support_i2c" tabindex="-1">I2C <a class="header-anchor" href="#firmware_support_i2c" aria-label="Permalink to &quot;I2C {#firmware_support_i2c}&quot;">​</a></h3><p>The driver is <a href="./../modules/modules_driver_distance_sensor#ll40ls">ll40ls</a>, which is built into firmware by either of the following keys:</p><ul><li><code>CONFIG_COMMON_DISTANCE_SENSOR=y</code>: the common set of rangefinder drivers, which includes this one.</li><li><code>CONFIG_DRIVERS_DISTANCE_SENSOR_LL40LS=y</code>: this driver on its own.</li></ul><p>Most boards set <code>CONFIG_COMMON_DISTANCE_SENSOR</code>, so the I2C driver is present in most firmware.</p><h3 id="firmware_support_pwm" tabindex="-1">PWM <a class="header-anchor" href="#firmware_support_pwm" aria-label="Permalink to &quot;PWM {#firmware_support_pwm}&quot;">​</a></h3><p>The driver is <a href="./../modules/modules_driver_distance_sensor#ll40ls-pwm">ll40ls_pwm</a>, which is built into firmware by the key <code>CONFIG_DRIVERS_DISTANCE_SENSOR_LL40LS_PWM=y</code>. It is not part of the common set of rangefinder drivers, so it is only present in the firmware for boards that set that key.</p><p>The PWM driver also requires the <code>pwm_input</code> driver (<code>CONFIG_DRIVERS_PWM_INPUT=y</code>).</p><h2 id="px4_configuration" tabindex="-1">PX4 Configuration <a class="header-anchor" href="#px4_configuration" aria-label="Permalink to &quot;PX4 Configuration {#px4_configuration}&quot;">​</a></h2><p>The rangefinder is enabled using the parameter <a href="./../advanced_config/parameter_reference#SENS_EN_LL40LS">SENS_EN_LL40LS</a>. The value to set depends on the connection, as described below. Reboot the flight controller after changing the parameter.</p><p>If the parameter is not available in <em>QGroundControl</em> then the I2C driver is not in the firmware: see <a href="#firmware_support">Firmware Support</a>.</p><p>The configuration that is common to all rangefinders, such as the sensor position offsets used by the estimator, is covered in <a href="./../sensor/rangefinders#configuration">Rangefinders &gt; Configuration/Setup</a>.</p><h3 id="px4_configuration_i2c" tabindex="-1">I2C <a class="header-anchor" href="#px4_configuration_i2c" aria-label="Permalink to &quot;I2C {#px4_configuration_i2c}&quot;">​</a></h3><p>Set <a href="./../advanced_config/parameter_reference#SENS_EN_LL40LS">SENS_EN_LL40LS</a> to <code>2</code>.</p><p>The driver detects the hardware version of the connected sensor, and uses this to set the maximum range that PX4 will use:</p><ul><li>LIDAR-Lite v4 LED: 10 m</li><li>Other versions: 25 m or 35 m, depending on the detected hardware version</li></ul><p>The minimum range is 5 cm.</p><h3 id="px4_configuration_pwm" tabindex="-1">PWM <a class="header-anchor" href="#px4_configuration_pwm" aria-label="Permalink to &quot;PWM {#px4_configuration_pwm}&quot;">​</a></h3><p>Set <a href="./../advanced_config/parameter_reference#SENS_EN_LL40LS">SENS_EN_LL40LS</a> to <code>1</code>.</p><p>PX4 uses a range of 5 cm to 25 m for all versions of the sensor.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing {#testing}&quot;">​</a></h2><p>You can check that the driver is running using the <em>QGroundControl MAVLink Console</em>. For I2C:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ll40ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>For PWM:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ll40ls_pwm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>You can observe the published measurements with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">listener</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> distance_sensor</span></span></code></pre></div><p>The measurements can also be viewed in the <code>DISTANCE_SENSOR</code> message in the <em>QGroundControl MAVLink Inspector</em>. For more information see <a href="./../sensor/rangefinders#testing">Rangefinders &gt; Testing</a>.</p><h2 id="further_information" tabindex="-1">Further Information <a class="header-anchor" href="#further_information" aria-label="Permalink to &quot;Further Information {#further_information}&quot;">​</a></h2><ul><li><a href="./../modules/modules_driver_distance_sensor#ll40ls">Modules Reference: Distance Sensor (Driver): ll40ls</a></li><li><a href="./../modules/modules_driver_distance_sensor#ll40ls-pwm">Modules Reference: Distance Sensor (Driver): ll40ls_pwm</a></li><li><a href="https://static.garmin.com/pumac/LIDAR_Lite_v3_Operation_Manual_and_Technical_Specifications.pdf" target="_blank" rel="noreferrer">LIDAR-Lite v3 Operation Manual and Technical Specifications</a> (Garmin)</li></ul>',69))])}const S=n(u,[["render",m]]);export{L as __pageData,S as default};
